// Guide: GUIDE.md generated by the server with real state of the hub and this computer.
import { h, clear, icon } from '../dom.js';
import { api } from '../api.js';
import { store } from '../store.js';
import { outline, renderMarkdown } from '../markdown.js';
import { t } from '../i18n.js';

export default function create(ctx) {
  let key = '';
  let observer = null;
  let loading = false;
  const meta = h('div', { class: 'guide-meta' });
  const toc = h('nav', { class: 'toc', 'aria-label': t('ui.guide.toc') });
  const prose = h('article', { class: 'prose' });
  const el = h('div', { class: 'guide' }, toc, h('div', null, meta, prose));
  const scroller = document.getElementById('view');

  const go = (id) => {
    const t = prose.querySelector(`#${CSS.escape(id)}`);
    if (t) t.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth', block: 'start' });
  };

  prose.addEventListener('click', (ev) => {
    const a = ev.target.closest('a[href^="#"]');
    if (a) {
      ev.preventDefault();
      go(a.getAttribute('href').slice(1));
    }
  });

  async function load(force = false) {
    if (loading) return;
    loading = true;
    try {
      const { markdown } = await api.guide(force);
      const keepTop = scroller.scrollTop;
      clear(prose);
      prose.append(renderMarkdown(markdown));
      clear(toc);
      const heads = outline(markdown);
      for (const t of heads) toc.append(h('a', { href: `#${t.id}`, class: `l${t.level}`, 'data-id': t.id, onclick: (ev) => (ev.preventDefault(), go(t.id)) }, t.text));
      observe();
      scroller.scrollTop = keepTop;
      clear(meta);
      meta.append(h('span', null, t('ui.guide.updatedAt', { time: new Date().toLocaleTimeString('en-US') })), h('button', { class: 'btn small', type: 'button', onclick: () => load(true) }, icon('refresh', 15), t('ui.guide.reload')));
    } catch (e) {
      clear(prose);
      prose.append(h('div', { class: 'banner warn' }, icon('warn'), h('div', null, t('ui.guide.loadError'), e.message)));
    } finally {
      loading = false;
    }
  }

  function observe() {
    observer?.disconnect();
    observer = new IntersectionObserver(
      (entries) => {
        const vis = entries.filter((e) => e.isIntersecting).sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top)[0];
        if (!vis) return;
        for (const a of toc.querySelectorAll('a')) a.classList.toggle('on', a.dataset.id === vis.target.id);
      },
      { root: scroller, rootMargin: '0px 0px -75% 0px' },
    );
    prose.querySelectorAll('h2, h3').forEach((x) => observer.observe(x));
  }

  return {
    el,
    update() {
      const k = store.state?.watch ?? '';
      if (k !== key) {
        key = k;
        load();
      }
    },
    destroy() {
      observer?.disconnect();
    },
  };
}
